<?php require_once __DIR__.'/../funciones.php'; exigir_admin();$rs=$conn->query("SELECT u.id,u.nombre,u.usuario,u.creado_en,COUNT(p.id) pedidos FROM usuarios u LEFT JOIN pedidos p ON p.usuario_id=u.id WHERE u.rol='cliente' GROUP BY u.id ORDER BY u.creado_en DESC");?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clientes</title><link rel="stylesheet" href="../estilos.css"></head><body><?php include 'menu.php';?><main class="contenedor"><h1 class="titulo">Clientes registrados</h1><p class="muted">Solo se muestran cuentas con rol cliente.</p><div class="panel tabla-wrap"><table><tr><th>ID</th><th>Nombre</th><th>Usuario</th><th>Fecha de registro</th><th>Pedidos</th></tr><?php while($u=$rs->fetch_assoc()):?><tr><td><?=$u['id']?></td><td><?=e($u['nombre'])?></td><td><?=e($u['usuario'])?></td><td><?=e($u['creado_en'])?></td><td><?=$u['pedidos']?></td></tr><?php endwhile;?></table></div></main></body></html>
